KEYWORD_FRAMES = [
(["ethic", "confidential", "consent", "boundary", "law", "legal", "court", "custody",
  "report", "record", "testify", "dilemma", "gift"], "ethics"),
(["playroom", "play therapy", "toy", "toddler", "aggressive boy", "withdrawn",
  "bullied", "child who", "a child", "children who"], "child"),
(["group", "facilitat", "member"], "group"),
(["research", "design", "method", "writ", "measure", "proposal", "defence", "study", "data"], "research"),
(["crisis", "suicide", "violence", "disaster", "safety", "accident"], "crisis"),
(["assess", "genogram", "risk", "hypothes", "plan", "diagnos"], "assessment"),
(["supervis", "feedback", "consult", "reflect", "case presentation"], "supervision"),
(["culture", "elder", "faith", "community", "interpreter", "japa", "tribe"], "community"),
]


def choose_frame(text):
    low = text.lower()
    for keys, frame in KEYWORD_FRAMES:
        for k in keys:
            if k in low:
                return frame
    return None
